#include<stdio.h>
typedef long long unsigned U;
int main(int argc, char *argv[])
{
    U s,x,y,r;
    scanf("%llu %llu", &s, &x);
    if (s < x) { printf("0\n"); return 0; }
    if ((s - x) & 1) { printf("0\n"); return 0; }
    y = (s - x) / 2;
    if (x & y) { printf("0\n"); return 0; }
    if (x == 0) {
        printf("%llu\n", y > 0 ? 1ULL : 0ULL);
        return 0;
    }
    r = 1;
    for (U t = x; t; t >>= 1) if (t & 1) r <<= 1;
    if (y == 0) r -= 2;
    printf("%llu\n", r);
    return 0;
}

